/**
 * The built-in tutors: fan-made tribute caricatures generated by
 * scripts/build_tutor_avatar.py. Kept free of three.js so app state can
 * reference tutors without loading the 3D engine.
 */
export type Glasses = { eyeY: number; eyeX: number; depth: number; width: number; height: number };
export interface TutorPreset { id: TutorId; label: string; url: string; headScale: number; restingSmile: number; glasses: Glasses | null }
export type TutorId = "andrej" | "jensen";

export const TUTORS: Record<TutorId, TutorPreset> = {
    andrej: { id: "andrej", label: "Andrej", url: "/avatars/tutor-andrej.vrm", headScale: 1.18, restingSmile: 0.3, glasses: null },
    // Glasses in the raw head bone's frame (VRoid heads face -Z before rotateVRM0).
    jensen: { id: "jensen", label: "Jensen", url: "/avatars/tutor-jensen.vrm", headScale: 1.26, restingSmile: 0.26,
        glasses: { eyeY: 0.057, eyeX: 0.036, depth: -0.12, width: 0.064, height: 0.04 } },
};
export const DEFAULT_TUTOR: TutorId = "andrej";

export function isTutorId(value: unknown): value is TutorId {
    return typeof value === "string" && value in TUTORS;
}
